package com.gymie.shared.cardio

import kotlinx.serialization.Serializable

private const val REPEAT = "REPEAT"

/** Mirrors `CardioStepRequest` / `CardioStepResponse`: [type] a step type or `REPEAT`. */
@Serializable
data class CardioStepWire(
    val type: String,
    val repeatCount: Int? = null,
    val length: CardioLengthWire? = null,
    val targets: List<CardioTargetWire> = emptyList(),
    val note: String? = null,
    val steps: List<CardioStepWire>? = null,
)

/** [kind] `TIME` carries [seconds], `DISTANCE` a [distance], `OPEN` neither. */
@Serializable
data class CardioLengthWire(
    val kind: String,
    val seconds: Int? = null,
    val distance: CardioDistance? = null,
)

@Serializable
data class CardioTargetWire(
    val metric: CardioMetric,
    val min: Double,
    val max: Double,
)

/** The wire's flat steps as the tree; the server only ever sends a well-formed plan. */
fun List<CardioStepWire>.toPlan(): List<CardioStep> = map { it.toStep() }

fun List<CardioStep>.toWire(): List<CardioStepWire> =
    map { step ->
        when (step) {
            is CardioStep.Interval -> {
                step.toWire()
            }

            is CardioStep.Repeat -> {
                CardioStepWire(
                    REPEAT,
                    repeatCount = step.count,
                    note = step.note,
                    steps = step.steps.map { it.toWire() },
                )
            }
        }
    }

private fun CardioStepWire.toStep(): CardioStep =
    if (type == REPEAT) {
        CardioStep.Repeat(repeatCount ?: 0, steps.orEmpty().map { it.toStep() as CardioStep.Interval }, note)
    } else {
        CardioStep.Interval(
            CardioStepType.valueOf(type),
            length.toLength(),
            targets.map { CardioTarget(it.metric, it.min, it.max) },
            note,
        )
    }

private fun CardioLengthWire?.toLength(): CardioLength =
    when (this?.kind) {
        "TIME" -> CardioLength.Time(seconds ?: 0)
        "DISTANCE" -> distance?.let { CardioLength.Of(it) } ?: CardioLength.Open
        else -> CardioLength.Open
    }

private fun CardioStep.Interval.toWire() =
    CardioStepWire(
        type = type.name,
        length =
            when (length) {
                is CardioLength.Time -> CardioLengthWire("TIME", seconds = length.seconds)
                is CardioLength.Of -> CardioLengthWire("DISTANCE", distance = length.distance)
                CardioLength.Open -> CardioLengthWire("OPEN")
            },
        targets = targets.map { CardioTargetWire(it.metric, it.min, it.max) },
        note = note,
    )
